CREATE OR REPLACE VIEW ${catalog}.${schema_lc}.mv_sales_performance_agg
WITH METRICS LANGUAGE YAML AS $$
version: 1.1
comment: "Sales performance metrics with LOD logic: product -> country -> split value (on-the-fly country count)"
parameters:
