      WHERE (size(f_brand) = 0 OR array_contains(f_brand, brand_name))
      AND (size(f_country_group) = 0 OR array_contains(f_country_group, country_group))
      AND (size(f_country) = 0 OR array_contains(f_country, country_code))
      AND (size(f_year) = 0 OR array_contains(f_year, fiscal_year))
      AND (size(f_quarter) = 0 OR array_contains(f_quarter, fiscal_quarter))
      AND (size(f_month) = 0 OR array_contains(f_month, fiscal_month))
      AND (size(f_week) = 0 OR array_contains(f_week, fiscal_week))
      AND (size(f_product_type) = 0 OR array_contains(f_product_type, product_type))
      AND (size(f_new_repeat) = 0 OR array_contains(f_new_repeat, new_or_repeat))
      AND (p_weeks = 'Include all weeks' OR week_idx <= (SELECT MAX(week_idx) - 2 FROM ${catalog}.${schema_lc}.dim_week))
    ) base
    GROUP BY period, split_value, country_code, product_id) WHERE (size(f_pack_size) = 0 AND size(f_loyalty) = 0 AND p_split NOT IN ('Pack Size', 'Loyalty Group'))
    UNION ALL
    SELECT * FROM (SELECT period, split_value, country_code, product_id,
      COUNT(*) AS sold,
      COUNT_IF(NOT is_flagged) AS sold_wo,
      COUNT(score) AS n_ratings,
      COUNT_IF(rating_value = 1) AS n1,
      COUNT_IF(rating_value = 2) AS n2,
      SUM(score) AS sum_score,
      SUM(CASE WHEN NOT is_flagged THEN score END) AS sum_score_wo,
      COUNT(CASE WHEN NOT is_flagged THEN score END) AS n_ratings_wo
    FROM (
      SELECT CASE p_time WHEN 'Week' THEN w.fiscal_week WHEN 'Month' THEN w.fiscal_month WHEN 'Year' THEN w.fiscal_year ELSE w.fiscal_quarter END AS period,
        CASE p_split WHEN 'Country' THEN c.country_code WHEN 'Brand' THEN b.brand_name WHEN 'Product Type' THEN r.product_type WHEN 'New or Repeat Product' THEN r.new_or_repeat WHEN 'Pack Size' THEN ps.pack_size WHEN 'Loyalty Group' THEN cu.loyalty_group ELSE c.country_group END AS split_value,
        c.country_code AS country_code, d.product_id AS product_id, d.is_flagged AS is_flagged,
        d.rating_value AS rating_value,
        CASE WHEN p_scale = '4-star' THEN (CASE WHEN d.rating_scale_used = '5-star' THEN 1 + (d.rating_value - 1) * 0.75 ELSE d.rating_value END) ELSE (CASE WHEN d.rating_scale_used = '4-star' THEN 1 + (d.rating_value - 1) * 4.0 / 3 ELSE d.rating_value END) END AS score
      FROM ${catalog}.${schema_lc}.fact_sales d
    JOIN ${catalog}.${schema_lc}.dim_week w ON d.week_id = w.week_id
    JOIN ${catalog}.${schema_lc}.dim_country c ON d.country_id = c.country_id
    JOIN ${catalog}.${schema_lc}.dim_brand b ON d.brand_id = b.brand_id
    JOIN ${catalog}.${schema_lc}.dim_product r ON d.product_id = r.product_id
    JOIN ${catalog}.${schema_lc}.dim_pack_size ps ON d.pack_size_id = ps.pack_size_id
    JOIN ${catalog}.${schema_lc}.dim_customer cu ON d.customer_id = cu.customer_id
      WHERE (size(f_brand) = 0 OR array_contains(f_brand, b.brand_name))
      AND (size(f_country_group) = 0 OR array_contains(f_country_group, c.country_group))
      AND (size(f_country) = 0 OR array_contains(f_country, c.country_code))
      AND (size(f_year) = 0 OR array_contains(f_year, w.fiscal_year))
      AND (size(f_quarter) = 0 OR array_contains(f_quarter, w.fiscal_quarter))
      AND (size(f_month) = 0 OR array_contains(f_month, w.fiscal_month))
      AND (size(f_week) = 0 OR array_contains(f_week, w.fiscal_week))
      AND (size(f_product_type) = 0 OR array_contains(f_product_type, r.product_type))
      AND (size(f_new_repeat) = 0 OR array_contains(f_new_repeat, r.new_or_repeat))
      AND (size(f_pack_size) = 0 OR array_contains(f_pack_size, ps.pack_size))
      AND (size(f_loyalty) = 0 OR array_contains(f_loyalty, cu.loyalty_group))
      AND (p_weeks = 'Include all weeks' OR w.week_idx <= (SELECT MAX(week_idx) - 2 FROM ${catalog}.${schema_lc}.dim_week))
    ) base
    GROUP BY period, split_value, country_code, product_id) WHERE NOT (size(f_pack_size) = 0 AND size(f_loyalty) = 0 AND p_split NOT IN ('Pack Size', 'Loyalty Group'))
  ),
  product_scores AS (
    SELECT *, sum_score / NULLIF(n_ratings, 0) AS pr, sum_score_wo / NULLIF(n_ratings_wo, 0) AS pr_wo FROM product_lod
  )
  SELECT period, split_value, country_code,
    SUM(pr * sold) / NULLIF(SUM(CASE WHEN pr IS NOT NULL THEN sold END), 0) AS wt_pr,
    SUM(pr_wo * sold_wo) / NULLIF(SUM(CASE WHEN pr_wo IS NOT NULL THEN sold_wo END), 0) AS wt_pr_wo,
    AVG(pr) AS avg_pr,
    AVG(pr_wo) AS avg_pr_wo,
    SUM(n1) / NULLIF(SUM(n_ratings), 0) AS share_1s,
    SUM(n2) / NULLIF(SUM(n_ratings), 0) AS share_2s,
    SUM(n_ratings) / NULLIF(SUM(sold), 0) AS response_rate,
    SUM(sold) AS units_sold,
    COUNT(DISTINCT product_id) AS n_products,
    AVG(CASE WHEN pr >= CASE WHEN p_scale = '4-star' THEN 3.6 ELSE 4.5 END THEN 1.0 WHEN pr IS NOT NULL THEN 0.0 END) AS hit_rate
  FROM product_scores
  GROUP BY period, split_value, country_code
dimensions:
  - name: period
    expr: period
  - name: split_value
    expr: split_value
  - name: country_code
    expr: country_code
measures:
  - name: Wt. Product Rating
    expr: SUM(wt_pr) / COUNT(DISTINCT country_code)
  - name: Wt. Product Rating excl. flagged
    expr: SUM(wt_pr_wo) / COUNT(DISTINCT country_code)
  - name: Avg. Product Rating
    expr: SUM(avg_pr) / COUNT(DISTINCT country_code)
  - name: Avg. Product Rating excl. flagged
    expr: SUM(avg_pr_wo) / COUNT(DISTINCT country_code)
  - name: Avg. Share of 1s
    expr: SUM(share_1s) / COUNT(DISTINCT country_code)
  - name: Avg. Share of 2s
    expr: SUM(share_2s) / COUNT(DISTINCT country_code)
  - name: Avg. Response Rate
    expr: SUM(response_rate) / COUNT(DISTINCT country_code)
  - name: Units Sold
    expr: SUM(units_sold)
  - name: Avg. Count of Products per Country
    expr: SUM(n_products) / COUNT(DISTINCT country_code)
  - name: Product Hit Rate
    expr: SUM(hit_rate) / COUNT(DISTINCT country_code)
$$;
CREATE OR REPLACE VIEW ${catalog}.${schema}.mv_sales_performance_star
WITH METRICS LANGUAGE YAML AS $$
version: 1.1
comment: "Sales performance metrics with LOD logic: product -> country -> split value (on-the-fly country count)"
parameters:
  - name: p_split
    data_type: string
    default: "'Country Group'"
  - name: p_time
    data_type: string
    default: "'Quarter'"
  - name: p_weeks
    data_type: string
    default: "'Exclude 2 weeks'"
  - name: p_scale
    data_type: string
    default: "'5-star'"
  - name: f_brand
    data_type: array<string>
    default: "array('Brand A')"
  - name: f_country_group
    data_type: array<string>
    default: "array()"
  - name: f_country
    data_type: array<string>
    default: "array()"
  - name: f_year
    data_type: array<string>
    default: "array()"
  - name: f_quarter
    data_type: array<string>
    default: "array()"
  - name: f_month
    data_type: array<string>
    default: "array()"
  - name: f_week
    data_type: array<string>
    default: "array()"
  - name: f_product_type
    data_type: array<string>
    default: "array()"
  - name: f_new_repeat
    data_type: array<string>
    default: "array()"
  - name: f_pack_size
    data_type: array<string>
    default: "array()"
  - name: f_loyalty
    data_type: array<string>
    default: "array()"
source: |
  WITH product_lod AS (
    SELECT period, split_value, country_code, product_id,
      COUNT(*) AS sold,
      COUNT_IF(NOT is_flagged) AS sold_wo,
      COUNT(score) AS n_ratings,
      COUNT_IF(rating_value = 1) AS n1,
      COUNT_IF(rating_value = 2) AS n2,
      SUM(score) AS sum_score,
      SUM(CASE WHEN NOT is_flagged THEN score END) AS sum_score_wo,
      COUNT(CASE WHEN NOT is_flagged THEN score END) AS n_ratings_wo
    FROM (
      SELECT CASE p_time WHEN 'Week' THEN w.fiscal_week WHEN 'Month' THEN w.fiscal_month WHEN 'Year' THEN w.fiscal_year ELSE w.fiscal_quarter END AS period,
        CASE p_split WHEN 'Country' THEN c.country_code WHEN 'Brand' THEN b.brand_name WHEN 'Product Type' THEN r.product_type WHEN 'New or Repeat Product' THEN r.new_or_repeat WHEN 'Pack Size' THEN ps.pack_size WHEN 'Loyalty Group' THEN cu.loyalty_group ELSE c.country_group END AS split_value,
        c.country_code AS country_code, d.product_id AS product_id, d.is_flagged AS is_flagged,
        d.rating_value AS rating_value,
        CASE WHEN p_scale = '4-star' THEN (CASE WHEN d.rating_scale_used = '5-star' THEN 1 + (d.rating_value - 1) * 0.75 ELSE d.rating_value END) ELSE (CASE WHEN d.rating_scale_used = '4-star' THEN 1 + (d.rating_value - 1) * 4.0 / 3 ELSE d.rating_value END) END AS score
      FROM ${catalog}.${schema}.fact_sales d
    JOIN ${catalog}.${schema}.dim_week w ON d.week_id = w.week_id
    JOIN ${catalog}.${schema}.dim_country c ON d.country_id = c.country_id
    JOIN ${catalog}.${schema}.dim_brand b ON d.brand_id = b.brand_id
    JOIN ${catalog}.${schema}.dim_product r ON d.product_id = r.product_id
    JOIN ${catalog}.${schema}.dim_pack_size ps ON d.pack_size_id = ps.pack_size_id
    JOIN ${catalog}.${schema}.dim_customer cu ON d.customer_id = cu.customer_id
      WHERE (size(f_brand) = 0 OR array_contains(f_brand, b.brand_name))
      AND (size(f_country_group) = 0 OR array_contains(f_country_group, c.country_group))
      AND (size(f_country) = 0 OR array_contains(f_country, c.country_code))
      AND (size(f_year) = 0 OR array_contains(f_year, w.fiscal_year))
      AND (size(f_quarter) = 0 OR array_contains(f_quarter, w.fiscal_quarter))
      AND (size(f_month) = 0 OR array_contains(f_month, w.fiscal_month))
      AND (size(f_week) = 0 OR array_contains(f_week, w.fiscal_week))
      AND (size(f_product_type) = 0 OR array_contains(f_product_type, r.product_type))
      AND (size(f_new_repeat) = 0 OR array_contains(f_new_repeat, r.new_or_repeat))
      AND (size(f_pack_size) = 0 OR array_contains(f_pack_size, ps.pack_size))
      AND (size(f_loyalty) = 0 OR array_contains(f_loyalty, cu.loyalty_group))
      AND (p_weeks = 'Include all weeks' OR w.week_idx <= (SELECT MAX(week_idx) - 2 FROM ${catalog}.${schema}.dim_week))
    ) base
    GROUP BY period, split_value, country_code, product_id
  ),
  product_scores AS (
    SELECT *, sum_score / NULLIF(n_ratings, 0) AS pr, sum_score_wo / NULLIF(n_ratings_wo, 0) AS pr_wo FROM product_lod
  )
  SELECT period, split_value, country_code,
    SUM(pr * sold) / NULLIF(SUM(CASE WHEN pr IS NOT NULL THEN sold END), 0) AS wt_pr,
    SUM(pr_wo * sold_wo) / NULLIF(SUM(CASE WHEN pr_wo IS NOT NULL THEN sold_wo END), 0) AS wt_pr_wo,
    AVG(pr) AS avg_pr,
    AVG(pr_wo) AS avg_pr_wo,
    SUM(n1) / NULLIF(SUM(n_ratings), 0) AS share_1s,
    SUM(n2) / NULLIF(SUM(n_ratings), 0) AS share_2s,
    SUM(n_ratings) / NULLIF(SUM(sold), 0) AS response_rate,
    SUM(sold) AS units_sold,
    COUNT(DISTINCT product_id) AS n_products,
    AVG(CASE WHEN pr >= CASE WHEN p_scale = '4-star' THEN 3.6 ELSE 4.5 END THEN 1.0 WHEN pr IS NOT NULL THEN 0.0 END) AS hit_rate
  FROM product_scores
  GROUP BY period, split_value, country_code
dimensions:
  - name: period
    expr: period
  - name: split_value
    expr: split_value
  - name: country_code
    expr: country_code
measures:
  - name: Wt. Product Rating
    expr: SUM(wt_pr) / COUNT(DISTINCT country_code)
  - name: Wt. Product Rating excl. flagged
    expr: SUM(wt_pr_wo) / COUNT(DISTINCT country_code)
  - name: Avg. Product Rating
    expr: SUM(avg_pr) / COUNT(DISTINCT country_code)
  - name: Avg. Product Rating excl. flagged
    expr: SUM(avg_pr_wo) / COUNT(DISTINCT country_code)
  - name: Avg. Share of 1s
    expr: SUM(share_1s) / COUNT(DISTINCT country_code)
  - name: Avg. Share of 2s
    expr: SUM(share_2s) / COUNT(DISTINCT country_code)
  - name: Avg. Response Rate
    expr: SUM(response_rate) / COUNT(DISTINCT country_code)
  - name: Units Sold
    expr: SUM(units_sold)
  - name: Avg. Count of Products per Country
    expr: SUM(n_products) / COUNT(DISTINCT country_code)
  - name: Product Hit Rate
    expr: SUM(hit_rate) / COUNT(DISTINCT country_code)
$$;
